<?php
namespace App\Http\Controllers;
use App\Models\BhudevProfile;use App\Models\Service;use Illuminate\Http\Request;
class PublicBhudevController extends Controller { public function index(Request $request){$query=BhudevProfile::publiclyVisible()->with(['services','user'])->orderBy('display_name');if($request->filled('q')){$term=$request->string('q')->toString();$query->where(function($q)use($term){$q->where('display_name','like','%'.$term.'%')->orWhere('city','like','%'.$term.'%')->orWhere('state','like','%'.$term.'%')->orWhere('expertise','like','%'.$term.'%');});}if($request->filled('city'))$query->where('city','like','%'.$request->string('city')->toString().'%');if($request->filled('service'))$query->whereHas('services',fn($q)=>$q->where('slug',$request->string('service')->toString()));return view('pages.bhudevs',['profiles'=>$query->paginate(12)->withQueryString(),'services'=>Service::where('is_active',true)->orderBy('name')->get()]);}public function show(string $slug){$profile=BhudevProfile::publiclyVisible()->with(['user','services','images'])->where('slug',$slug)->firstOrFail();return view('pages.bhudev-show',compact('profile'));} }
